begin;
update public.books b set metadata=jsonb_set(b.metadata,'{geographicReview,regionalPlaces}',(select jsonb_agg(case when r->>'id'='regional-jefferson' then jsonb_set(r,'{place,regionalOutline}',(r#>'{place,regionalOutline}')||'{"labelAnchor":[-90.3084,34.9957],"labelAnchorMeaning":"typographic-position-on-source-boundary-not-fictional-location"}'::jsonb) else r end order by ord) from jsonb_array_elements(b.metadata#>'{geographicReview,regionalPlaces}') with ordinality a(r,ord))) where b.id='sound-and-fury';
update public.books b set metadata=jsonb_set(b.metadata,'{geographicReview,regionalPlaces}',(select jsonb_agg(case when r->>'id'='regional-mottson' then jsonb_set(r,'{place,regionalOutline}',(r#>'{place,regionalOutline}')||'{"labelAnchor":[-88.889,30.1398],"labelAnchorMeaning":"typographic-position-on-source-boundary-not-fictional-location"}'::jsonb) else r end order by ord) from jsonb_array_elements(b.metadata#>'{geographicReview,regionalPlaces}') with ordinality a(r,ord))) where b.id='sound-and-fury';
update public.books b set metadata=jsonb_set(b.metadata,'{geographicReview,regionalPlaces}',(select jsonb_agg(case when r->>'id'='regional-little-girl-bay' then jsonb_set(r,'{place,regionalOutline}',(r#>'{place,regionalOutline}')||'{"labelAnchor":[-88.0698,49.0014],"labelAnchorMeaning":"typographic-position-on-source-boundary-not-fictional-location"}'::jsonb) else r end order by ord) from jsonb_array_elements(b.metadata#>'{geographicReview,regionalPlaces}') with ordinality a(r,ord))) where b.id='gatsby';
update public.place_descriptions set metadata=jsonb_set(metadata,'{regionalOutline}',(metadata->'regionalOutline')||'{"labelAnchor":[-91.654,31.2558],"labelAnchorMeaning":"typographic-position-on-source-boundary-not-fictional-location"}'::jsonb) where book_id='sound-and-fury' and place_id='mississippi';
commit;select 'Four label anchors updated' as verified;